<?php
 namespace Pterodactyl\Services\Dezerx\Importer; use Throwable; use FTP\Connection; use Illuminate\Support\Facades\Log; class FtpClient implements RemoteFilesystem { use RemoteWalk; private const TIMEOUT = 20; private ?Connection $ftp = null; public function __construct(private readonly Credentials $credentials) { } public function open(): array { $refusal = $this->credentials->refusal(); if ($refusal !== null) { return ['ok' => false, 'error' => $refusal, 'banner' => null]; } $ftp = @ftp_connect((string) $this->credentials->connectAddress(), $this->credentials->port, self::TIMEOUT); if ($ftp === false) { return ['ok' => false, 'error' => 'That host did not answer on port ' . $this->credentials->port . '.', 'banner' => null]; } try { $authenticated = @ftp_login($ftp, $this->credentials->username, $this->credentials->secret); } catch (Throwable $exception) { @ftp_close($ftp); return ['ok' => false, 'error' => 'That login was refused: ' . $exception->getMessage(), 'banner' => null]; } if (!$authenticated) { @ftp_close($ftp); return ['ok' => false, 'error' => 'That username and password were refused by the host.', 'banner' => null]; } @ftp_set_option($ftp, FTP_USEPASVADDRESS, false); @ftp_pasv($ftp, true); @ftp_set_option($ftp, FTP_TIMEOUT_SEC, self::TIMEOUT); $this->ftp = $ftp; return ['ok' => true, 'error' => null, 'banner' => @ftp_systype($ftp) ?: null]; } public function listing(string $path): ?array { if ($this->ftp === null) { return null; } $path = $this->clean($path); $listed = @ftp_mlsd($this->ftp, $path); $entries = $listed === false ? $this->fromRawList($path) : $this->fromMlsd($listed, $path); if ($entries === null) { return null; } usort($entries, fn (array $a, array $b) => [$b['directory'], $a['name']] <=> [$a['directory'], $b['name']]); return $entries; } private function fromMlsd(array $listed, string $path): array { $entries = []; foreach ($listed as $row) { $name = (string) ($row['name'] ?? ''); $type = (string) ($row['type'] ?? ''); if ($name === '' || $name === '.' || $name === '..' || $type === 'cdir' || $type === 'pdir') { continue; } $directory = $type === 'dir'; $size = isset($row['size']) ? (int) $row['size'] : 0; if (!$directory && $size === 0) { $size = max(0, (int) @ftp_size($this->ftp, $path . '/' . $name)); } $entries[] = ['name' => $name, 'size' => $size, 'directory' => $directory]; } return $entries; } private function fromRawList(string $path): ?array { $raw = @ftp_rawlist($this->ftp, $path); if ($raw === false) { return null; } $entries = []; foreach ($raw as $line) { if (preg_match('/^([\-dl])\S*\s+\S+\s+\S+\s+\S+\s+(\d+)\s+\S+\s+\S+\s+\S+\s+(.+)$/', (string) $line, $found) !== 1) { continue; } $name = trim($found[3]); if ($name === '' || $name === '.' || $name === '..' || $found[1] === 'l') { continue; } $entries[] = [ 'name' => $name, 'size' => $found[1] === 'd' ? 0 : (int) $found[2], 'directory' => $found[1] === 'd', ]; } return $entries; } public function openReadStream(string $path): mixed { if ($this->ftp === null) { return false; } $stream = fopen('php://temp/maxmemory:8388608', 'w+b'); if ($stream === false) { return false; } try { if (!@ftp_fget($this->ftp, $stream, $this->clean($path), FTP_BINARY)) { fclose($stream); return false; } } catch (Throwable $exception) { fclose($stream); Log::warning('An import could not read a remote file', [ 'host' => $this->credentials->host, 'path' => $path, 'error' => $exception->getMessage(), ]); return false; } rewind($stream); return $stream; } public function isDirectory(string $path): bool { if ($this->ftp === null) { return false; } $path = $this->clean($path); $here = @ftp_pwd($this->ftp); if (!@ftp_chdir($this->ftp, $path)) { return false; } if (is_string($here)) { @ftp_chdir($this->ftp, $here); } return true; } public function close(): void { if ($this->ftp !== null) { @ftp_close($this->ftp); } $this->ftp = null; } private function clean(string $path): string { $path = trim(str_replace('\\', '/', $path)); return $path === '' ? '.' : $path; } } 